package ai.taskforge.api;
import ai.taskforge.domain.*; import ai.taskforge.knowledge.KnowledgeService; import ai.taskforge.repo.TaskRepository; import ai.taskforge.service.CurrentUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/assistant") public class AssistantController { private final TaskRepository tasks;private final KnowledgeService knowledge;private final CurrentUser current;public AssistantController(TaskRepository t,KnowledgeService k,CurrentUser c){tasks=t;knowledge=k;current=c;} record Request(@NotBlank @Size(max=2000) String message){} record Reply(String answer,String tool,List<String> items,List<KnowledgeService.Hit> sources){} @PostMapping("/chat") Reply chat(@Valid @RequestBody Request request){String q=request.message().toLowerCase();var visible=current.elevated()?tasks.findAllBy():tasks.findByAssigneeId(current.get().getId());if(q.contains("deployment")||q.contains("document")||q.contains("knowledge")||q.startsWith("find ")){var result=knowledge.answer(request.message());return new Reply(result.answer(),"searchKnowledgeBase",List.of(),result.sources());}if(q.contains("blocked")){var list=visible.stream().filter(t->t.getStatus()==TaskStatus.BLOCKED).map(Task::getTitle).toList();return new Reply(list.isEmpty()?"You have no blocked tasks.":"Blocked tasks: "+String.join(", ",list),"searchTasks",list,List.of());}if(q.contains("overdue")){var list=visible.stream().filter(t->t.getDueDate()!=null&&t.getDueDate().isBefore(LocalDate.now())&&t.getStatus()!=TaskStatus.COMPLETED).map(Task::getTitle).toList();return new Reply(list.isEmpty()?"You have no overdue tasks.":"Overdue tasks: "+String.join(", ",list),"searchTasks",list,List.of());}var ordered=visible.stream().filter(t->t.getStatus()!=TaskStatus.COMPLETED).sorted(Comparator.comparingInt(Task::getPriorityScore).reversed()).limit(3).map(Task::getTitle).toList();return new Reply(ordered.isEmpty()?"Your visible workload is clear.":"Prioritize: "+String.join(" → ",ordered),"getWorkloadSummary",ordered,List.of());} }
